{"code": "def validate_cert_chain(chain: List[Certificate]) -> dict[str, Any]:
    """Validate a TLS certificate chain from leaf to root and record compliance. Each cert[i].issuer must equal cert[i+1].subject to form a valid
    chain. Records the tls.chain.validated decision via
    orgops.compliance.record_decision.
    """
    record_decision = __import__("orgops.compliance", fromlist=["record_decision"]).record_decision

    result: dict[str, Any]
    if not chain:
        result = {"valid": False, "depth": 0, "error": "empty chain"}
    elif len(chain) == 1:
        is_valid = _is_self_signed(chain[0])
        result = {
            "valid": is_valid,
            "depth": 1,
            "self_signed": True,
            "error": None if is_valid else "single cert is not self-signed",
        }
    else:
        errors: list[str] = []
        for i in range(len(chain) - 1):
            expected = chain[i].issuer
            actual = chain[i + 1].subject
            if expected != actual:
                errors.append(
                    f"break at {i}: issuer={expected!r} != subject={actual!r}"
                )
        is_valid = len(errors) == 0
        result = {
            "valid": is_valid,
            "depth": len(chain),
            "errors": errors,
            "root_self_signed": _is_self_signed(chain[-1]),
        }

    record_decision("tls.chain.validated", result["valid"])
    return result
